<?php require __DIR__.'/includes/db.php'; require __DIR__.'/includes/auth.php'; require_login(); $rows=$pdo->query("SELECT s.*, (SELECT COUNT(*) FROM student_files f WHERE f.student_id=s.id) file_count FROM students s ORDER BY s.created_at DESC")->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Directory</title><link rel="stylesheet" href="admin.css"></head><body><aside class="sidebar"><div class="logo">C<span>ampusFlow</span></div><div class="nav-label">WORKSPACE</div><a class="active" href="view_students.php">▦ &nbsp; Students</a><a href="../frontend/register.html">＋ &nbsp; Registration form</a><div class="side-bottom"><a href="logout.php">↪ &nbsp; Sign out</a></div></aside><main class="main"><header class="header"><div><div class="crumb">WORKSPACE / STUDENTS</div><h1>Student directory</h1><p>Manage student records and supporting documents.</p></div><div class="avatar">AD</div></header><section class="stats"><article><span>Total students</span><strong><?=count($rows)?></strong><small>Registered profiles</small></article><article><span>Uploaded files</span><strong><?=array_sum(array_column($rows,'file_count'))?></strong><small>Images and documents</small></article><article><span>Active courses</span><strong><?=count(array_unique(array_column($rows,'course')))?></strong><small>Across the directory</small></article></section><section class="table-card"><div class="table-head"><div><h2>All students</h2><p>Student records stored in MySQL</p></div><a class="add-btn" href="add_student.php">＋ Add student</a></div><div class="search"><input id="search" placeholder="Search name, roll number or course..."></div><div class="table-scroll"><table><thead><tr><th>STUDENT</th><th>ROLL NUMBER</th><th>COURSE</th><th>FILES</th><th>JOINED</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?=e($r['name'])?></b><small><?=e($r['email'])?></small></td><td><span class="roll"><?=e($r['roll_number'])?></span></td><td><?=e($r['course'])?></td><td><?=e($r['file_count'])?> files</td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><a href="student_detail.php?id=<?=$r['id']?>">View</a> · <a href="edit_student.php?id=<?=$r['id']?>">Edit</a> · <form class="inline" method="post" action="delete_student.php" onsubmit="return confirm('Delete this student and their file records?')"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Delete</button></form></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6" class="empty">No students yet. Add a student to get started.</td></tr><?php endif; ?></tbody></table></div></section><footer>CampusFlow · Student administration</footer></main><script>document.getElementById('search').addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')})</script></body></html>
